LOCK TABLE provider_templates,provider_model_templates,provider_template_research,provider_model_template_research IN ACCESS EXCLUSIVE MODE;
CREATE TABLE catalog_schema_rollback(table_name text NOT NULL,row_key text NOT NULL,original jsonb NOT NULL,PRIMARY KEY(table_name,row_key));
INSERT INTO catalog_schema_rollback SELECT 'provider_templates',id,to_jsonb(p) FROM provider_templates p;
INSERT INTO catalog_schema_rollback SELECT 'provider_model_templates',row_id::text,to_jsonb(m) FROM provider_model_templates m;
INSERT INTO catalog_schema_rollback SELECT 'provider_template_research',id,to_jsonb(r) FROM provider_template_research r;
INSERT INTO catalog_schema_rollback SELECT 'provider_model_template_research',id,to_jsonb(r) FROM provider_model_template_research r;
DO $$ DECLARE t text; c record; BEGIN
 FOREACH t IN ARRAY ARRAY['provider_templates','provider_model_templates'] LOOP
  FOR c IN SELECT conname,pg_get_constraintdef(oid) definition FROM pg_constraint WHERE conrelid=t::regclass AND contype IN ('c','f','u') LOOP
   INSERT INTO catalog_schema_rollback VALUES('constraint',t||':'||c.conname,jsonb_build_object('table',t,'name',c.conname,'definition',c.definition));
  END LOOP;
 END LOOP;
END $$;
