DROP TRIGGER personal_model_template_guard ON catalog_model_book;
UPDATE catalog_model_book m SET availability='deprecated' FROM provider_model_template_research r WHERE r.id=m.source_id AND r.unresolved_fields->'operations'->>'status'='unsupported' AND lower(r.unresolved_fields->'operations'->>'reason') LIKE '%deprecat%';
CREATE TABLE catalog_source(id text PRIMARY KEY,source_refs jsonb NOT NULL,source_records jsonb NOT NULL,acquisition_recipes jsonb NOT NULL,observations jsonb NOT NULL,state text NOT NULL CHECK(state IN ('in_progress','complete')));
INSERT INTO catalog_source SELECT id,source_refs,to_jsonb(r),model_info_sources,jsonb_build_object('field_metadata',field_metadata,'authentication',authentication,'endpoint_config',endpoint_config),state::text FROM provider_template_research r;
INSERT INTO catalog_source SELECT id,source_refs,to_jsonb(r),model_info_sources,jsonb_build_object('field_metadata',field_metadata,'unresolved_fields',unresolved_fields,'resolution_plan',resolution_plan),state::text FROM provider_model_template_research r;
