CREATE TABLE catalog_model_thinking_effort(model_id uuid NOT NULL REFERENCES catalog_model_book(row_id) ON DELETE CASCADE,level text NOT NULL CHECK(level IN ('low','medium','high','xhigh','max')),provider_value text NOT NULL CHECK(length(btrim(provider_value))>0),PRIMARY KEY(model_id,level));
CREATE TABLE catalog_model_format(model_id uuid NOT NULL REFERENCES catalog_model_book(row_id) ON DELETE CASCADE,capability text NOT NULL,format text NOT NULL CHECK(length(btrim(format))>0),position integer NOT NULL CHECK(position>=0),PRIMARY KEY(model_id,capability,position),UNIQUE(model_id,capability,format));
CREATE TABLE catalog_price_book(id uuid PRIMARY KEY,provider_catalog_id text NOT NULL REFERENCES catalog_provider_book(id),key text NOT NULL,organization_id bigint,user_id bigint,region text,plan text,service_tier text,request_mode text NOT NULL DEFAULT 'standard' CHECK(request_mode IN ('standard','batch')),source_id text REFERENCES catalog_source(id),evidence_status text NOT NULL CHECK(evidence_status IN ('imported','verified','estimated','user_defined')),CHECK((organization_id IS NULL)=(user_id IS NULL)),FOREIGN KEY(organization_id,user_id) REFERENCES organization_members(organization_id,user_id),UNIQUE(provider_catalog_id,key));
CREATE TABLE catalog_model_price_book(model_id uuid NOT NULL REFERENCES catalog_model_book(row_id) ON DELETE CASCADE,price_book_id uuid NOT NULL REFERENCES catalog_price_book(id) ON DELETE RESTRICT,route_key text NOT NULL DEFAULT '',PRIMARY KEY(model_id,price_book_id,route_key));
CREATE TABLE catalog_price_component(id uuid PRIMARY KEY,price_book_id uuid NOT NULL REFERENCES catalog_price_book(id) ON DELETE CASCADE,parent_id uuid REFERENCES catalog_price_component(id) ON DELETE CASCADE,feature text NOT NULL,kind text NOT NULL CHECK(kind IN ('usage','free','included','model_billing')),usage_kind text CHECK(usage_kind IN ('fixed','tiered_token','scheduled')),rate_kind text CHECK(rate_kind IN ('token','audio','image','video','request','credit')),measured_by text CHECK(measured_by IN ('input_tokens','total_tokens')),timezone text,from_hour smallint,to_hour smallint,audio_kind text CHECK(audio_kind IN ('duration','character','utf8_bytes')),CHECK((from_hour IS NULL AND to_hour IS NULL) OR(from_hour>=0 AND from_hour<to_hour AND to_hour<=24)));
CREATE UNIQUE INDEX catalog_price_root_identity ON catalog_price_component(price_book_id,feature) WHERE parent_id IS NULL;
CREATE TABLE catalog_price_rate(id uuid PRIMARY KEY,component_id uuid NOT NULL REFERENCES catalog_price_component(id) ON DELETE CASCADE,parent_rate_id uuid REFERENCES catalog_price_rate(id) ON DELETE CASCADE,position integer NOT NULL CHECK(position>=0),kind text NOT NULL,amount numeric,currency text,quantity numeric,credits numeric,direction text,unit text,cache_mode text,from_tokens numeric,to_tokens numeric,resolution text,quality text,audio boolean,service_tier text,CHECK(amount IS NULL OR(amount>=0 AND amount<1e12 AND amount NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric))),CHECK(credits IS NULL OR(credits>=0 AND credits<1e12)),CHECK(quantity IS NULL OR(quantity>0 AND quantity<=18446744073709551615 AND quantity=trunc(quantity))),CHECK(currency IS NULL OR currency ~ '^[A-Z]{3}$'),CHECK(cache_mode IS NULL OR cache_mode IN ('separate_rate','estimated_rate','standard_input_rate','included','unsupported')),CHECK(from_tokens IS NULL OR(from_tokens>=0 AND from_tokens=trunc(from_tokens))),CHECK(to_tokens IS NULL OR(to_tokens>from_tokens AND to_tokens=trunc(to_tokens))),UNIQUE(component_id,position,kind));
CREATE TABLE catalog_price_parameter(rate_id uuid NOT NULL REFERENCES catalog_price_rate(id) ON DELETE CASCADE,name text NOT NULL,value text NOT NULL,PRIMARY KEY(rate_id,name));
CREATE TABLE catalog_price_billing(price_book_id uuid PRIMARY KEY REFERENCES catalog_price_book(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('subscription','free','request','credit')),product text,plan text,description text,fee_amount numeric,fee_currency text,fee_period text,amount_per_credit numeric,currency text,CHECK(fee_amount IS NULL OR(fee_amount>=0 AND fee_amount<1e12)),CHECK(amount_per_credit IS NULL OR(amount_per_credit>=0 AND amount_per_credit<1e12)));
CREATE TABLE catalog_price_allowance(price_book_id uuid NOT NULL REFERENCES catalog_price_book(id) ON DELETE CASCADE,position integer NOT NULL,unit text NOT NULL,quota numeric,reset_period text,CHECK(quota IS NULL OR(quota>0 AND quota<=18446744073709551615 AND quota=trunc(quota))),PRIMARY KEY(price_book_id,position));
CREATE TABLE catalog_fallback_book(id uuid PRIMARY KEY,key text NOT NULL UNIQUE,priority integer NOT NULL,rule_kind text NOT NULL CHECK(rule_kind IN ('provider_inference','capability')),model_pattern text NOT NULL,fill_missing boolean NOT NULL,source_id text REFERENCES catalog_source(id));
CREATE TABLE catalog_fallback_provider(rule_id uuid NOT NULL REFERENCES catalog_fallback_book(id) ON DELETE CASCADE,provider_catalog_id text NOT NULL REFERENCES catalog_provider_book(id),PRIMARY KEY(rule_id,provider_catalog_id));
CREATE TABLE catalog_fallback_fact(rule_id uuid NOT NULL REFERENCES catalog_fallback_book(id) ON DELETE CASCADE,field text NOT NULL CHECK(field IN ('litellm_provider','max_input_tokens','max_output_tokens','mode','supports_adaptive_thinking','supports_assistant_prefill','supports_function_calling','supports_legacy_thinking','supports_mid_conversation_system','supports_parallel_function_calling','supports_pdf_input','supports_per_turn_control','supports_prompt_caching','supports_reasoning','supports_response_schema','supports_system_messages','supports_tool_choice','supports_tool_search','supports_vision','supports_web_search','thinking_always_on','thinking_on_by_default')),text_value text,integer_value bigint,boolean_value boolean,CHECK(num_nonnulls(text_value,integer_value,boolean_value)=1),PRIMARY KEY(rule_id,field));
